-- log_players levels
rsql select level, min(season), max(season), count(*) from log_players group by level
-- NFL players: mean overall by unit, age band and season (all rostered NFL players in the yearly row)
rsql select season, case when person__player__position in ('OT','IOL') then 'OL' when person__player__position in ('DT','EDGE') then 'DL' when person__player__position in ('CB','S') then 'DB' else person__player__position end unit, case when person__player__age < 25 then 'a<25' when person__player__age < 29 then 'a25-28' when person__player__age < 33 then 'a29-32' else 'a33+' end band, count(*) n, round(avg(overall),2) ovr from log_players where level = 'NFL' and season >= 2025 and person__player__position in ('OT','IOL','DT','EDGE','LB','CB','S','RB','QB','WR','TE') group by season, unit, band order by unit, band, season
